75:   function roundRect(x,y,width,height,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,width,height,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
76:   function updateHUD(){remainLabel.textContent=Math.round(cup)+'%';scoreLabel.textContent=Math.round(caught)+'%';angleLabel.textContent=angle+'°';}
