145:     // Aim marker gently indicates where the stream is headed while pouring.
146:     if(angle>=22&&cup>0){const t=(targetTop-g.cupY)/Math.max(1,Math.sin(angle*Math.PI/180)*160+40);const aimX=g.cupX+Math.cos(angle*Math.PI/180)*34+Math.sin(angle*Math.PI/180)*18+(Math.sin(angle*Math.PI/180)*160+22)*t;ctx.strokeStyle='#d3eaf8';ctx.setLineDash([4,6]);ctx.beginPath();ctx.moveTo(aimX,targetTop-7);ctx.lineTo(aimX,targetTop+4);ctx.stroke();ctx.setLineDash([]);}
