148:     updateHUD();
149:   }
150:   let delta=16;
151:   function frame(t){delta=last?Math.min(40,t-last):16;last=t;draw();requestAnimationFrame(frame);}
152:   requestAnimationFrame(frame);
153: })();
154: </script>
